python3 -c "import os,json,urllib.request,urllib.error; token=os.environ.get('IVX_OWNER_TOKEN','').strip(); req=urllib.request.Request('https://api.ivxholding.com/api/ivx/developer-deploy/status',headers={'Accept':'application/json','Authorization':'Bearer '+token});
try:
 with urllib.request.urlopen(req,timeout=30) as r:
  b=json.load(r); print(json.dumps({'httpStatus':r.status,'ok':b.get('ok'),'serviceId':b.get('serviceId'),'liveCommit':b.get('liveCommit') or b.get('runtimeCommit'),'render':b.get('render'),'keys':sorted(b.keys())}))
except urllib.error.HTTPError as e:
 print(json.dumps({'httpStatus':e.code,'error':json.loads(e.read().decode()).get('error','authorization failed')}))"

